"use client";

import { useActionState, useOptimistic } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { createVinyl } from "@/lib/actions/vinyls";
import { Loader2, Upload } from "lucide-react";
import { useFormStatus } from "react-dom";
import { useRouter } from "next/navigation";
import { useQueryClient } from "@tanstack/react-query";

interface CollectionFormProps {
  onSuccess?: () => void;
}

function SubmitButton() {
  const { pending } = useFormStatus();
  return (
    <Button type="submit" disabled={pending} className="rounded-full">
      {pending ? (
        <>
          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
          Adding...
        </>
      ) : (
        <>
          <Upload className="h-4 w-4 mr-2" />
          Add to Collection
        </>
      )}
    </Button>
  );
}

export function CollectionForm({ onSuccess }: CollectionFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();
  const [state, formAction] = useActionState(createVinyl, { error: null });

  const handleSubmit = async (formData: FormData) => {
    // Set as collection item (not listed)
    formData.set("isListed", "false");
    formData.set("isInCollection", "true");

    const result = await formAction(formData);
    
    if (!result?.error) {
      // Invalidate queries to refresh collection
      queryClient.invalidateQueries({ queryKey: ["vinyls", "collection"] });
      onSuccess?.();
    }
  };

  return (
    <form action={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="title">Title *</Label>
          <Input id="title" name="title" required />
        </div>
        <div className="space-y-2">
          <Label htmlFor="artist">Artist *</Label>
          <Input id="artist" name="artist" required />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="genre">Genre *</Label>
          <Input id="genre" name="genre" required />
        </div>
        <div className="space-y-2">
          <Label htmlFor="year">Year</Label>
          <Input id="year" name="year" type="number" />
        </div>
      </div>

      <div className="space-y-2">
        <Label htmlFor="condition">Condition *</Label>
        <Select name="condition" required>
          <SelectTrigger>
            <SelectValue placeholder="Select condition" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="sealed">Sealed</SelectItem>
            <SelectItem value="mint">Mint</SelectItem>
            <SelectItem value="near-mint">Near Mint</SelectItem>
            <SelectItem value="very-good">Very Good</SelectItem>
            <SelectItem value="good">Good</SelectItem>
            <SelectItem value="fair">Fair</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-2">
        <Label htmlFor="description">Description</Label>
        <Textarea id="description" name="description" rows={3} />
      </div>

      {state?.error && (
        <p className="text-sm text-destructive">{state.error}</p>
      )}

      <SubmitButton />
    </form>
  );
}
